const decode = (row: string) => row.replace(/(\d+)(\D)/g, (_, n: string, ch: string) => ch.repeat(Number(n)));

/** the frames, bud first: each a row of letters per pixel row */
export const LOTUS_FRAMES: readonly (readonly string[])[] = ENCODED.map((f) => f.map(decode));
